// This is not autogenerated.
package resource

import (
	"encoding/json"
	"reflect"
	"testing"
)

// MeshSync carries a hand-written mirror of Resource (pkg/model/resource.go,
// meshery/meshsync#582) and will replace it with this generated type. These
// tests pin the generated struct to the mirror's field names, Go types and
// JSON tags, so that replacement stays a change of import only.

func TestResourceMatchesMeshSyncMirror(t *testing.T) {
	want := []struct {
		name, json string
		typ        reflect.Type
	}{
		{"ID", "id,omitempty", reflect.TypeOf("")},
		{"Platform", "platform", reflect.TypeOf("")},
		{"ScopeID", "scopeId,omitempty", reflect.TypeOf("")},
		{"Kind", "kind", reflect.TypeOf("")},
		{"Name", "name,omitempty", reflect.TypeOf("")},
		{"Labels", "labels,omitempty", reflect.TypeOf(map[string]string{})},
		{"Metadata", "metadata,omitempty", reflect.TypeOf(map[string]interface{}{})},
		{"ConnectionID", "connectionId,omitempty", reflect.TypeOf("")},
		{"SchemaVersion", "schemaVersion", reflect.TypeOf("")},
	}
	rt := reflect.TypeOf(Resource{})
	if rt.NumField() != len(want) {
		t.Fatalf("Resource has %d fields, want %d", rt.NumField(), len(want))
	}
	for i, w := range want {
		f := rt.Field(i)
		if f.Name != w.name {
			t.Errorf("field %d = %s, want %s", i, f.Name, w.name)
			continue
		}
		if got := f.Tag.Get("json"); got != w.json {
			t.Errorf("%s json tag = %q, want %q", f.Name, got, w.json)
		}
		// Metadata is core.Map, a named map[string]any: values of the
		// mirror's map[string]interface{} assign to it without conversion.
		if !w.typ.AssignableTo(f.Type) || !f.Type.ConvertibleTo(w.typ) || f.Type.Kind() != w.typ.Kind() {
			t.Errorf("%s type = %s, want %s", f.Name, f.Type, w.typ)
		}
	}
}

func TestResourceWireForm(t *testing.T) {
	r := Resource{
		Platform:      "kubernetes",
		ScopeID:       "8a7c2d3e-0f1b-4c5d-9e6f-7a8b9c0d1e2f",
		Kind:          "Pod",
		Name:          "web-0",
		Labels:        map[string]string{"app": "web"},
		Metadata:      map[string]interface{}{"namespace": "default"},
		SchemaVersion: "resources.meshery.io/v1beta1",
	}
	raw, err := json.Marshal(r)
	if err != nil {
		t.Fatal(err)
	}
	const want = `{"platform":"kubernetes","scopeId":"8a7c2d3e-0f1b-4c5d-9e6f-7a8b9c0d1e2f","kind":"Pod","name":"web-0","labels":{"app":"web"},"metadata":{"namespace":"default"},"schemaVersion":"resources.meshery.io/v1beta1"}`
	if string(raw) != want {
		t.Errorf("wire form\n got %s\nwant %s", raw, want)
	}
	var back Resource
	if err := json.Unmarshal(raw, &back); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(back.Labels, r.Labels) || back.ScopeID != r.ScopeID || back.Metadata["namespace"] != "default" {
		t.Errorf("round trip lost data: %+v", back)
	}
}
